import type { MetadataRoute } from 'next';
import { siteConfig } from '@/lib/site-config';

export default function manifest(): MetadataRoute.Manifest {
  return {
    name: siteConfig.name,
    short_name: 'Manatee Fun',
    description:
      "Small-group, family-friendly snorkel-with-manatee tours from Pete's Pier Marina in Crystal River, Florida.",
    start_url: '/',
    display: 'standalone',
    background_color: '#F4F2EC',
    theme_color: '#0D3532',
    orientation: 'portrait',
    categories: ['travel', 'outdoors', 'lifestyle'],
    icons: [
      // Generated by src/app/icon.tsx and src/app/apple-icon.tsx (there is
      // no favicon.ico). TODO: add 192×192 and 512×512 for installability.
      { src: '/icon', sizes: '64x64', type: 'image/png' },
      { src: '/apple-icon', sizes: '180x180', type: 'image/png' },
    ],
  };
}
